043e \\u0443\\u043d\\u0456\\u0432\\u0435\\u0440\\u0441\\u0438\\u0442\\u0435\\u0442\\u0443 \\u00ab\\u041b\\u044c\\u0432\\u0456\\u0432\\u0441\\u044c\\u043a\\u043e\\u0457 \\u043f\\u043e\\u043b\\u0456\\u0442\\u0435\\u0445\\u043d\\u0456\\u043a\\u0438\\u00bb, \\u0449\\u043e\\u0431 \\u043f\\u0440\\u043e\\u0434\\u043e\\u0432\\u0436\\u0443\\u0432\\u0430\\u0442\\u0438 \\u0432\\u0438\\u0432\\u0447\\u0430\\u0442\\u0438 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d. \\u0423\\u0436\\u0435 \\u0442\\u043e\\u0434\\u0456 \\u041e\\u043b\\u0435\\u0433 \\u043f\\u0440\\u0430\\u0446\\u044e\\u0432\\u0430\\u0432 \\u0433\\u0440\\u0430\\u0444\\u0456\\u0447\\u043d\\u0438\\u043c \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0435\\u0440\\u043e\\u043c (\\u0444\\u0440\\u0456\\u043b\\u0430\\u043d\\u0441\\u0435\\u0440\\u043e\\u043c). \\u041d\\u0430\\u0436\\u0430\\u043b\\u044c \\u043d\\u0430\\u0432\\u0447\\u0430\\u043d\\u043d\\u044f \\u043f\\u043e \\u0441\\u0456\\u043c\\u0435\\u0439\\u043d\\u0438\\u043c \\u043e\\u0431\\u0441\\u0442\\u0430\\u0432\\u0438\\u043d\\u0430\\u043c \\u043f\\u0440\\u0438\\u0439\\u0448\\u043b\\u043e\\u0441\\u044c \\u0437\\u0430\\u0432\\u0435\\u0440\\u0448\\u0438\\u0442\\u0438, \\u043d\\u0435 \\u043f\\u0440\\u043e\\u0431\\u0443\\u0432\\u0448\\u0438 \\u0432 \\u0443\\u043d\\u0456\\u0432\\u0435\\u0440\\u0441\\u0438\\u0442\\u0435\\u0442\\u0456 \\u043d\\u0430\\u0432\\u0456\\u0442\\u044c \\u0440\\u043e\\u043a\\u0443. \\u041f\\u043e\\u0432\\u0435\\u0440\\u043d\\u0443\\u0432\\u0448\\u0438\\u0441\\u044c \\u0443 2019\\u0440. \\u0432 \\u0440\\u0456\\u0434\\u043d\\u0435 \\u043c\\u0456\\u0441\\u0442\\u043e \\u0414\\u0440\\u043e\\u0433\\u043e\\u0431\\u0438\\u0447, \\u041e\\u043b\\u0435\\u0433 \\u043f\\u0435\\u0440\\u0435\\u0439\\u0448\\u043e\\u0432 \\u0456\\u0437 \\u0444\\u0440\\u0456\\u043b\\u0430\\u043d\\u0441\\u0443 \\u0434\\u043e \\u0441\\u0442\\u0430\\u0446\\u0456\\u043e\\u043d\\u0430\\u0440\\u043d\\u043e\\u0457 \\u0440\\u043e\\u0431\\u043e\\u0442\\u0438 \\u0433\\u0440\\u0430\\u0444\\u0456\\u0447\\u043d\\u0438\\u043c \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0435\\u0440\\u043e\\u043c. \\u0422\\u0430\\u043a \\u043f\\u0440\\u043e\\u0439\\u0448\\u043e\\u0432 \\u0440\\u0456\\u043a. \\u0420\\u043e\\u0431\\u043e\\u0442\\u0430 \\u0442\\u0432\\u043e\\u0440\\u0447\\u0430 \\u0430\\u043b\\u0435 \\u0441\\u043a\\u043e\\u0440\\u043e \\u043f\\u0435\\u0440\\u0435\\u0439\\u0448\\u043b\\u0430 \\u0443 \\u0440\\u0443\\u0442\\u0438\\u043d\\u043d\\u0443, \\u043b\\u0438\\u0448\\u0435 \\u043c\\u0430\\u043b\\u044e\\u0432\\u0430\\u043d\\u043d\\u044f \\u0440\\u044f\\u0442\\u0443\\u0432\\u0430\\u043b\\u043e \\u043c\\u0438\\u0442\\u0446\\u044f \\u0442\\u0430 \\u043d\\u0430\\u0434\\u0430\\u0432\\u0430\\u043b\\u043e \\u0434\\u0440\\u0443\\u0433\\u0435 \\u0434\\u0438\\u0445\\u0430\\u043d\\u043d\\u044f.\\u2028\\u0417\\u0430\\u0440\\u0430\\u0437 \\u0411\\u0430\\u0440\\u0430\\u043d \\u041e.\\u0410. \\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e \\u043c\\u0430\\u043b\\u044e\\u0454, \\u0441\\u0442\\u0432\\u043e\\u0440\\u044e\\u0454 \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u0438 \\u043e\\u043b\\u0456\\u0439\\u043d\\u0438\\u043c\\u0438 \\u0444\\u0430\\u0440\\u0431\\u0430\\u043c\\u0438, \\u0448\\u0443\\u043a\\u0430\\u0454 \\u0446\\u0456\\u043a\\u0430\\u0432\\u0456 \\u0441\\u044e\\u0436\\u0435\\u0442\\u0438 \\u0442\\u0430 \\u0432\\u0435\\u0434\\u0435 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0456\\u0439 \\u0431\\u043b\\u043e\\u0433 \\u0443\\u043a\\u0440\\u0430\\u0457\\u043d\\u0441\\u044c\\u043a\\u043e\\u044e \\u0443 \\u0456\\u043d\\u0441\\u0442\\u0430\\u0433\\u0440\\u0430\\u043c\\u0456, \\u0434\\u0435 \\u043c\\u0430\\u043b\\u044e\\u0454 \\u0442\\u0430 \\u0434\\u0456\\u043b\\u0438\\u0442\\u044c\\u0441\\u044f \\u0441\\u0432\\u043e\\u0454\\u044e \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044e \\u0437 \\u0443\\u0441\\u0456\\u043c\\u0430.\\u2028\\u2028\\\\r\\\\n\\u00ab\\u042f \\u0437\\u0430\\u0432\\u0436\\u0434\\u0438 \\u0432\\u0456\\u0434\\u0447\\u0443\\u0432\\u0430\\u