\u043a\\u0442\\u0443\\u0440\\u0438 \\u041a\\u0438\\u0457\\u0432\\u0441\\u044c\\u043a\\u043e\\u0433\\u043e \\u043c\\u0456\\u0441\\u044c\\u043a\\u0432\\u0438\\u043a\\u043e\\u043d\\u043a\\u043e\\u043c\\u0443.\\\\r\\\\n  \\u0417 1959 \\u0440\\u043e\\u043a\\u0443 \\u0436\\u0438\\u0432\\u0435 \\u0432 \\u041a\\u0438\\u0454\\u0432\\u0456. \\u0412\\u0456\\u0434 1980 \\u0440\\u043e\\u043a\\u0443 - \\u0447\\u043b\\u0435\\u043d \\u0421\\u043f\\u0456\\u043b\\u043a\\u0438 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a\\u0456\\u0432 \\u0421\\u0420\\u0421\\u0420.\\\\r\\\\n  1975-1983 \\u0440\\u0440. - \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a-\\u043a\\u043e\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u043e\\u0440 \\u0456 \\u0437\\u0430\\u0432\\u0456\\u0434\\u0443\\u0432\\u0430\\u0447 \\u0432\\u0456\\u0434\\u0434\\u0456\\u043b\\u043e\\u043c \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u044c\\u043e\\u0433\\u043e \\u043e\\u0444\\u043e\\u0440\\u043c\\u043b\\u0435\\u043d\\u043d\\u044f \\u043a\\u043d\\u0438\\u0433\\u0438 \\u0443 \\u0432\\u0438\\u0434\\u0430\\u0432\\u043d\\u0438\\u0446\\u0442\\u0432\\u0456 \\u0434\\u0438\\u0442\\u044f\\u0447\\u043e\\u0457 \\u043b\\u0456\\u0442\\u0435\\u0440\\u0430\\u0442\\u0443\\u0440\\u0438 \\u00ab\\u0412\\u0435\\u0441\\u0435\\u043b\\u043a\\u0430\\u00bb (\\u0412\\u0435\\u0441\\u0435\\u043b\\u043a\\u0430).\\\\r\\\\n 1987-1992 \\u0440\\u0440. - \\u0447\\u043b\\u0435\\u043d \\u0421\\u043f\\u0456\\u043b\\u043a\\u0438 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a\\u0456\\u0432 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438, \\u0432\\u0456\\u0434\\u043f\\u043e\\u0432\\u0456\\u0434\\u0430\\u043b\\u044c\\u043d\\u0438\\u0439 \\u0441\\u0435\\u043a\\u0440\\u0435\\u0442\\u0430\\u0440 \\u041a\\u0438\\u0457\\u0432\\u0441\\u044c\\u043a\\u043e\\u0457 \\u043e\\u0440\\u0433\\u0430\\u043d\\u0456\\u0437\\u0430\\u0446\\u0456\\u0457 \\u0421\\u043f\\u0456\\u043b\\u043a\\u0438 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a\\u0456\\u0432 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438.\\\\r\\\\n 1996-2001 \\u0440\\u0440. - \\u0437\\u0430\\u0441\\u0442\\u0443\\u043f\\u043d\\u0438\\u043a \\u0433\\u043e\\u043b\\u043e\\u0432\\u0438 \\u041d\\u0430\\u0446\\u0456\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0457 \\u0441\\u043f\\u0456\\u043b\\u043a\\u0438 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a\\u0456\\u0432 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438.\\\\r\\\\n 1997-2012 \\u0440\\u0440. - \\u0432\\u0447\\u0435\\u043d\\u0438\\u0439 \\u0441\\u0435\\u043a\\u0440\\u0435\\u0442\\u0430\\u0440 \\u0432\\u0456\\u0434\\u0434\\u0456\\u043b\\u0435\\u043d\\u044c \\u0441\\u0438\\u043d\\u0442\\u0435\\u0437\\u0443 \\u043f\\u043b\\u0430\\u0441\\u0442\\u0438\\u0447\\u043d\\u0438\\u0445 \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432 \\u0456 \\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0442\\u0432\\u043e\\u0440\\u0447\\u043e\\u0433\\u043e \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432\\u0430 \\u041d\\u0430\\u0446\\u0456\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0457 \\u0430\\u043a\\u0430\\u0434\\u0435\\u043c\\u0456\\u0457 \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438.\\\\r\\\\n \\u0417\\u0430\\u0441\\u043b\\u0443\\u0436\\u0435\\u043d\\u0438\\u0439 \\u0434\\u0456\\u044f\\u0447 \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438 (1990). \\u041d\\u0430\\u0440\\u043e\\u0434\\u043d\\u0438\\u0439 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438 (1998). \\u0427\\u043b\\u0435\\u043d-\\u043a\\u043e\\u0440\\u0435\\u0441\\u043f\\u043e\\u043d\\u0434\\u0435\\u043d\\u0442 \\u041d\\u0430\\u0446\\u0456\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0457 \\u0430\\u043a\\u0430\\u0434\\u0435\\u043c\\u0456\\u0457 \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432 (2004). \\\\r\\\\n \\u041f\\u043e\\u0447\\u0435\\u0441\\u043d\\u0438\\u0439 \\u0433\\u0440\\u043e\\u043c\\u0430\\u0434\\u044f\\u043d\\u0438\\u043d \\u043c\\u0456\\u0441\\u0442 \\u0412\\u0456\\u043d\\u043d\\u0456\\u043f\\u0435\\u0433\\u0430 \\u0456 \\u0411\\u0440\\u0430\\u043d\\u0434\\u043e\\u043d\\u0430 (\\u041a\\u0430\\u043d\\u0430\\u0434\\u0430) (1990).\\\\r\\\\n \\u041d\\u0430\\u0433\\u043e\\u0440\\u043e\\u0434\\u0436\\u0435\\u043d\\u0438\\u0439: \\u0411\\u0440\\u043e\\u043d\\u0437\\u043e\\u0432\\u043e\\u044e \\u043c\\u0435\\u0434\\u0430\\u043b\\u043b\\u044e \\u00ab\\u0417\\u0430 \\u0443\\u0441\\u043f\\u0456\\u0445\\u0438, \\u0434\\u043e\\u0441\\u044f\\u0433\\u043d\\u0443\\u0442\\u0456 \\u0432 \\u043d\\u0430\\u0440\\u043e\\u0434\\u043d\\u043e\\u043c\\u0443 \\u0433\\u043e\\u0441\\u043f\\u043e\\u0434\\u0430\\u0440\\u0441\\u0442\\u0432\\u0456 \\u0421\\u0420\\u0421\\u0420\\u00bb (1978), \\u0434\\u0438\\u043f\\u043b\\u043e\\u043c\\u043e\\u043c \\u0456\\u043c. \\u0413\\u0435\\u043e\\u0440\\u0433\\u0456\\u044f \\u042f\\u043a\\u0443\\u0442\\u043e\\u0432\\u0438\\u0447\\u0430 \\u043d\\u0430 \\u043a\\u043e\\u043d\\u043a\\u0443\\u0440\\u0441\\u0456 \\u00ab\\u041c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432\\u043e \\u043a\\u043d\\u0438\\u0433\\u0438 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438\\u00bb (2003), \\u0441\\u0440\\u0456\\u0431\\u043d\\u043e\\u044e (2004) \\u0456 \\u0437\\u043e\\u043b\\u043e\\u0442\\u043e\\u044e (2010) \\u043c\\u0435\\u0434\\u0430\\u043b\\u044f\\u043c\\u0438 \\u0410\\u043a\\u0430\\u0434\\u0435\\u043c\\u0456\\u0457 \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438, \\u043e\\u0440\\u0434\\u0435\\u043d\\u043e\\u043c \\u00ab\\u0417\\u0430 \\u0437\\u0430\\u0441\\u043b\\u0443\\u0433\\u0438\\u00bb III \\u0441\\u0442\\u0443\\u043f\\u0435\\u043d\\u044f (2009). \\u041b\\u0430\\u0443\\u0440\\u0435\\u0430\\u0442 \\u043b\\u0456\\u0442\\u0435\\u0440\\u0430\\u0442\\u0443\\u0440\\u043d\\u043e-\\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u044c\\u043a\\u043e\\u0457 \\u043f\\u0440\\u0435\\u043c\\u0456\\u0457 \\u0456\\u043c. \\u041e\\u043b\\u0435\\u043d\\u0438 \\u041f\\u0447\\u0456\\u043b\\u043a\\u0438 (2003) \\u0442\\u0430 \\u043f\\u0440\\u0435\\u043c\\u0456\\u0457 \\u041a\\u0430\\u0431\\u0456\\u043d\\u0435\\u0442\\u0443 \\u043c\\u0456\\u043d\\u0456\\u0441\\u0442\\u0440\\u0456\\u0432 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438 \\u0456\\u043c. \\u041b\\u0435\\u0441\\u0456 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u043a\\u0438 (2004).\\\\r\\\\n  \\u0417 1977 \\u0440\\u043e\\u043a\\u0443 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a \\u0454 \\u043d\\u0435\\u0437\\u043c\\u0456\\u043d\\u043d\\u0438\\u043c \\u0443\\u0447\\u0430\\u0441\\u043d\\u0438\\u043a\\u043e\\u043c \\u043f\\u0440\\u0435\\u0441\\u0442\\u0438\\u0436\\u043d\\u0438\\u0445 \\u0432\\u0438\\u0441\\u0442\\u0430\\u0432\\u043e\\u043a \\u044f\\u043a \\u0432 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0456, \\u0442\\u0430\\u043a \\u0456 \\u0437\\u0430 \\u0457\\u0457 \\u043c\\u0435\\u0436\\u0430\\u043c\\u0438. \\u0419\\u043e\\u0433\\u043e \\u0440\\u043e\\u0431\\u043e\\u0442\\u0438 \\u0435\\u043a\\u0441\\u043f\\u043e\\u043d\\u0443\\u044e\\u0442\\u044c\\u0441\\u044f \\u0456 \\u0437\\u0431\\u0435\\u0440\\u0456\\u0433\\u0430\\u044e\\u0442\\u044c\\u0441\\u044f \\u0432 \\u041d\\u0430\\u0446\\u0456\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u043c\\u0443 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u044c\\u043e\\u043c\\u0443 \\u043c\\u0443\\u0437\\u0435\\u0457 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438, \\u0425\\u0430\\u0440\\u043a\\u0456\\u0432\\u0441\\u044c\\u043a\\u043e\\u043c\\u0443, \\u0412\\u0456\\u043d\\u043d\\u0438\\u0446\\u044c\\u043a\\u043e\\u043c\\u0443, \\u041c\\u0438\\u043a\\u043e\\u043b\\u0430\\u0457\\u0432\\u0441\\u044c\\u043a\\u043e\\u043c\\u0443, \\u0427\\u0435\\u0440\\u043d\\u0456\\u0433\\u0456\\u0432\\u0441\\u044c\\u043a\\u043e\\u043c\\u0443, \\u041f\\u043e\\u043b\\u0442\\u0430\\u0432\\u0441\\u044c\\u043a\\u043e\\u043c\\u0443, \\u0425\\u0435\\u0440\\u0441\\u043e\\u043d\\u0441\\u044c\\u043a\\u043e\\u043c\\u0443, \\u0417\\u0430\\u043f\\u043e\\u0440\\u0456\\u0437\\u044c\\u043a\\u043e\\u043c\\u0443 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0456\\u0445 \\u043c\\u0443\\u0437\\u0435\\u044f\\u0445, \\u0406\\u0437\\u043c\\u0430\\u0457\\u043b\\u044c\\u0441\\u044c\\u043a\\u0438\\u0439 \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u043d\\u0456\\u0439 \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u0457, \\u041c\\u0456\\u043d\\u0456\\u0441\\u0442\\u0435\\u0440\\u0441\\u0442\\u0432\\u0456 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0443\\u0440\\u0438 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438, \\u041a\\u0443\\u0440\\u0441\\u044c\\u043a\\u0456\\u0439 \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u043d\\u0456\\u0439 \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u0457, \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u0457 \\u041c\\u0456\\u0440\\u043e (\\u0427\\u0435\\u0445\\u0456\\u044f), \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u0457 \\u041c\\u0430\\u043d\\u0456\\u0442\\u043e\\u0431\\u0441\\u044c\\u043a\\u043e\\u0433\\u043e \\u0423\\u043d\\u0456\\u0432\\u0435\\u0440\\u0441\\u0438\\u0442\\u0435\\u0442\\u0443 (\\u041a\\u0430\\u043d\\u0430\\u0434\\u0430), \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u0457 \\u00ab\\u0421\\u043b\\u0430\\u0432\\u0430\\u00bb (\\u0424\\u0440\\u0430\\u043d\\u0446\\u0456\\u044f), \\u041a\\u043e\\u043b\\u0435\\u043a\\u0446\\u0456\\u0457 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0441\\u044c\\u043a\\u043e\\u0457 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u044c\\u043e\\u0457 \\u0440\\u0430\\u0434\\u0438 \\u041c\\u0430\\u043d\\u0456\\u0442\\u043e\\u0431\\u0438 (\\u041a\\u0430\\u043d\\u0430\\u0434\\u0430), \\u043a\\u043e\\u043b\\u0435\\u043a\\u0446\\u0456\\u0457 \\u043c\\u0438\\u0442\\u0440\\u043e\\u043f\\u043e\\u043b\\u0438\\u0442\\u0430 \\u041a\\u0430\\u043d\\u0430\\u0434\\u0438 \\u0411\\u043b\\u0430\\u0436\\u0435\\u043d\\u043d\\u0456\\u0448\\u043e\\u0433\\u0