(4297,'98f85796-9f8f-4a56-b1f1-2ba3ecfbff25','98f8580a-ea0b-4ff9-8338-08dde9d4a394',NULL,1,'query','{\"connection\":\"mysql\",\"bindings\":[],\"sql\":\"insert into `user_bios` (`user_id`, `language`, `text`) values (61217, \'uk\', \'\\u041f\\u0440\\u0438\\u0432\\u0435\\u0442\\u0441\\u0442\\u0432\\u0443\\u044e \\u0432\\u0441\\u0435\\u0445 \\u043b\\u044e\\u0431\\u0438\\u0442\\u0435\\u043b\\u0435\\u0439 \\u0436\\u0438\\u0432\\u043e\\u043f\\u0438\\u0441\\u0438! \\u041c\\u0435\\u043d\\u044f \\u0437\\u043e\\u0432\\u0443\\u0442 \\u0418\\u0440\\u0438\\u043d\\u0430 \\u0420\\u043e\\u0433\\u043e\\u0437\\u0430. \\u0412 1997\\u0433. \\u043e\\u043a\\u043e\\u043d\\u0447\\u0438\\u043b\\u0430 \\u041a\\u0438\\u0435\\u0432\\u0441\\u043a\\u0438\\u0439 \\u0433\\u043e\\u0441\\u0443\\u0434\\u0430\\u0440\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442 \\u0434\\u0435\\u043a\\u043e\\u0440\\u0430\\u0442\\u0438\\u0432\\u043d\\u043e-\\u043f\\u0440\\u0438\\u043a\\u043b\\u0430\\u0434\\u043d\\u043e\\u0433\\u043e \\u0438\\u0441\\u043a\\u0443\\u0441\\u0441\\u0442\\u0432\\u0430 \\u0438 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430 \\u0438\\u043c\\u0435\\u043d\\u0438 \\u041c. \\u0411\\u043e\\u0439\\u0447\\u0443\\u043a\\u0430 \\u043f\\u043e \\u043a\\u0432\\u0430\\u043b\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u0438 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a-\\u043c\\u0430\\u0441\\u0442\\u0435\\u0440.\\\\r\\\\n\\\\r\\\\n\\u0412 \\u043d\\u0430\\u0441\\u0442\\u043e\\u044f\\u0449\\u0435\\u0435 \\u0432\\u0440\\u0435\\u043c\\u044f, \\u043f\\u0440\\u043e\\u0444\\u0435\\u0441\\u0441\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e \\u043f\\u0438\\u0448\\u0443 \\u043d\\u0430 \\u0437\\u0430\\u043a\\u0430\\u0437: \\u043f\\u043e\\u0440\\u0442\\u0440\\u0435\\u0442\\u044b \\u043f\\u043e \\u0444\\u043e\\u0442\\u043e\\u0433\\u0440\\u0430\\u0444\\u0438\\u0438, \\u043d\\u0430\\u0442\\u044e\\u0440\\u043c\\u043e\\u0440\\u0442\\u044b, \\u043f\\u0435\\u0439\\u0437\\u0430\\u0436\\u0438, \\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u043d\\u0443\\u044e \\u0436\\u0438\\u0432\\u043e\\u043f\\u0438\\u0441\\u044c, \\u0432\\u0438\\u0442\\u0440\\u0430\\u0436\\u0438 \\u043d\\u0430 \\u0441\\u0442\\u0435\\u043a\\u043b\\u0435 \\u0434\\u043b\\u044f \\u043e\\u0444\\u043e\\u0440\\u043c\\u043b\\u0435\\u043d\\u0438\\u044f \\u0438\\u043d\\u0442\\u0435\\u0440\\u044c\\u0435\\u0440\\u0430, \\u0430 \\u0442\\u0430\\u043a\\u0436\\u0435 \\u0434\\u0435\\u043b\\u0430\\u044e \\u043a\\u043e\\u043f\\u0438\\u0438 \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d \\u0432\\u0435\\u043b\\u0438\\u043a\\u0438\\u0445 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a\\u043e\\u0432, \\u043f\\u0440\\u0438 \\u044d\\u0442\\u043e\\u043c, \\u0432\\u0441\\u0435\\u0433\\u0434\\u0430 \\u0441\\u0442\\u0430\\u0440\\u0430\\u044e\\u0441\\u044c \\u043c\\u0430\\u043a\\u0441\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u043e \\u043f\\u0440\\u0438\\u0431\\u043b\\u0438\\u0437\\u0438\\u0442\\u044c\\u0441\\u044f \\u043a \\u0438\\u0437\\u043e\\u0431\\u0440\\u0430\\u0436\\u0435\\u043d\\u0438\\u044e \\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 \\u043f\\u043e\\u043b\\u043e\\u0442\\u0435\\u043d, \\u043a\\u0430\\u043a \\u043f\\u043e \\u0446\\u0432\\u0435\\u0442\\u0443, \\u0442\\u0430\\u043a \\u0438 \\u043f\\u043e \\u043d\\u0430\\u0441\\u0442\\u0440\\u043e\\u0435\\u043d\\u0438\\u044e. \\u0418\\u043d\\u043e\\u0433\\u0434\\u0430, \\u043f\\u0440\\u0438\\u043d\\u0438\\u043c\\u0430\\u044e \\u0437\\u0430\\u043a\\u0430\\u0437\\u044b \\u043d\\u0430 \\u0441\\u043e\\u0437\\u0434\\u0430\\u043d\\u0438\\u0435 \\u044d\\u043a\\u0441\\u043a\\u043b\\u044e\\u0437\\u0438\\u0432\\u043d\\u044b\\u0445 \\u0441\\u0443\\u043c\\u043e\\u0447\\u0435\\u043a \\u0438\\u0437 \\u0431\\u0438\\u0441\\u0435\\u0440\\u0430.\\\\r\\\\n\\\\r\\\\n\\u0418\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u044e \\u0440\\u0430\\u0437\\u043d\\u0443\\u044e \\u0442\\u0435\\u0445\\u043d\\u0438\\u043a\\u0443: \\u043c\\u0430\\u0441\\u043b\\u043e \\u043d\\u0430 \\u0445\\u043e\\u043b\\u0441\\u0442\\u0435, \\u043a\\u0430\\u0440\\u0430\\u043d\\u0434\\u0430\\u0448, \\u043f\\u0430\\u0441\\u0442\\u0435\\u043b\\u044c, \\u0430\\u043a\\u0432\\u0430\\u0440\\u0435\\u043b\\u044c \\u043d\\u0430 \\u0431\\u0443\\u043c\\u0430\\u0433\\u0435 \\u0438 \\u0432\\u0438\\u0442\\u0440\\u0430\\u0436\\u043d\\u044b\\u0435 \\u043a\\u0440\\u0430\\u0441\\u043a\\u0438 \\u043d\\u0430 \\u0441\\u0442\\u0435\\u043a\\u043b\\u0435. \\u0420\\u0430\\u0431\\u043e\\u0442\\u0430\\u044f \\u043d\\u0430\\u0434 \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u0430\\u043c\\u0438, \\u043e\\u0440\\u0438\\u0435\\u043d\\u0442\\u0438\\u0440\\u0443\\u044e\\u0441\\u044c \\u043d\\u0430 \\u0442\\u0435\\u0445\\u043d\\u0438\\u043a\\u0443 \\u043a\\u043b\\u0430\\u0441\\u0441\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0436\\u0438\\u0432\\u043e\\u043f\\u0438\\u0441\\u0438, \\u0430 \\u0442\\u0430\\u043a\\u0436\\u0435 \\u0441\\u0442\\u0430\\u0432\\u043b\\u044e \\u0434\\u043b\\u044f \\u0441\\u0435\\u0431\\u044f \\u0437\\u0430\\u0434\\u0430\\u0447\\u0443 - \\u043a\\u0430\\u043a \\u043c\\u043e\\u0436\\u043d\\u043e \\u0431\\u043e\\u043b\\u0435\\u0435 \\u0442\\u043e\\u0447\\u043d\\u043e \\u0438 \\u043e\\u0431\\u044a\\u0435\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e \\u043e\\u0442\\u043e\\u0431\\u0440\\u0430\\u0437\\u0438\\u0442\\u044c \\u0434\\u0435\\u0439\\u0441\\u0442\\u0432\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c. \\u0412 \\u0441\\u0432\\u043e\\u0438\\u0445 \\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u0445, \\u043e\\u0447\\u0435\\u043d\\u044c \\u0447\\u0430\\u0441\\u0442\\u043e \\u043f\\u0435\\u0440\\u0435\\u0434\\u0430\\u044e \\u0432\\u043f\\u0435\\u0447\\u0430\\u0442\\u043b\\u0435\\u043d\\u0438\\u044f \\u043e\\u0442 \\u043f\\u0443\\u0442\\u0435\\u0448\\u0435\\u0441\\u0442\\u0432\\u0438\\u0439.\\\\r\\\\n\\\\r\\\\n\\u0423\\u0447\\u04