(4358,'98f85797-2a01-4668-b637-eff18d792756','98f8580a-ea0b-4ff9-8338-08dde9d4a394',NULL,1,'query','{\"connection\":\"mysql\",\"bindings\":[],\"sql\":\"insert into `user_bios` (`user_id`, `language`, `text`) values (60991, \'uk\', \'\\u0420\\u043e\\u0434\\u0438\\u043b\\u0441\\u044f 3 \\u0430\\u0432\\u0433\\u0443\\u0441\\u0442\\u0430 1960 \\u0433. \\u0432 \\u041d\\u0438\\u043a\\u043e\\u043b\\u0430\\u0435\\u0432\\u0441\\u043a\\u043e\\u0439 \\u043e\\u0431\\u043b\\u0430\\u0441\\u0442\\u0438 \\u0432 \\u0441\\u0435\\u043c\\u044c\\u0435 \\u0432\\u043e\\u0435\\u043d\\u043d\\u043e\\u0441\\u043b\\u0443\\u0436\\u0430\\u0449\\u0435\\u0433\\u043e. \\u041f\\u0435\\u0440\\u0432\\u044b\\u043c \\u0443\\u0447\\u0438\\u0442\\u0435\\u043b\\u0435\\u043c \\u0440\\u0438\\u0441\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u0431\\u044b\\u043b \\u043e\\u0442\\u0435\\u0446. \\u041e\\u043a\\u043e\\u043d\\u0447\\u0438\\u043b \\u041e\\u0434\\u0435\\u0441\\u0441\\u043a\\u0438\\u0439 \\u0441\\u0435\\u043b\\u044c\\u0441\\u043a\\u043e\\u0445\\u043e\\u0437\\u044f\\u0439\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442 (1987 \\u0433.), \\u0430 \\u0432 1989 \\u0433\\u043e\\u0434\\u0443 - \\u0444\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442 \\u0433\\u0440\\u0430\\u0444\\u0438\\u043a\\u0438 \\u0438 \\u0436\\u0438\\u0432\\u043e\\u043f\\u0438\\u0441\\u0438 \\u041c\\u043e\\u0441\\u043a\\u043e\\u0432\\u0441\\u043a\\u043e\\u0433\\u043e \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442\\u0430 \\u0438\\u043c. \\u041d. \\u041a. \\u041a\\u0440\\u0443\\u043f\\u0441\\u043a\\u043e\\u0439 (\\u0437\\u0430\\u043e\\u0447\\u043d\\u043e). \\u0420\\u0430\\u0431\\u043e\\u0442\\u0430\\u043b \\u0432 \\u0443\\u0447\\u0440\\u0435\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f\\u0445 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0443\\u0440\\u044b \\u043a\\u0438\\u043d\\u043e- \\u0438 \\u0440\\u0430\\u0434\\u0438\\u043e\\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u043a\\u043e\\u043c, \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u043e\\u0440\\u043e\\u043c, \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a\\u043e\\u043c-\\u043e\\u0444\\u043e\\u0440\\u043c\\u0438\\u0442\\u0435\\u043b\\u0435\\u043c. \\u0416\\u0438\\u0432\\u043e\\u043f\\u0438\\u0441\\u044c\\u044e \\u0437\\u0430\\u043d\\u0438\\u043c\\u0430\\u044e\\u0441\\u044c \\u0441 1993 \\u0433\\u043e\\u0434\\u0430. \\u041f\\u0438\\u0448\\u0443 \\u043f\\u043e\\u0440\\u0442\\u0440\\u0435\\u0442\\u044b, \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u044b \\u0441 \\u043f\\u0435\\u0439\\u0437\\u0430\\u0436\\u0430\\u043c\\u0438, \\u0436\\u0430\\u043d\\u0440\\u043e\\u0432\\u044b\\u0435 \\u0440\\u0430\\u0431\\u043e\\u0442\\u044b. \\u0427\\u043b\\u0435\\u043d \\u0427\\u0435\\u0440\\u043d\\u0438\\u0433\\u043e\\u0432\\u0441\\u043a\\u043e\\u0433\\u043e \\u0442\\u0432\\u043e\\u0440\\u0447\\u0435\\u0441\\u043a\\u043e\\u0433\\u043e \\u043e\\u0431\\u044a\\u0435\\u0434\\u0438\\u043d\\u0435\\u043d\\u0438\\u044f \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a\\u043e\\u0432 \\\\\\\"\\u0414\\u0435\\u0441\\u043d\\u044f\\u043d\\u0441\\u043a\\u0430\\u044f \\u043f\\u0430\\u043b\\u0438\\u0442\\u0440\\u0430\\\\\\\" \\u0441 2006 \\u0433\\u043e\\u0434\\u0430. \\u0423\\u0447\\u0430\\u0441\\u0442\\u0432\\u043e\\u0432\\u0430\\u043b \\u0432 \\u0433\\u043e\\u0440\\u043e\\u0434\\u0441\\u043a\\u0438\\u0445, \\u043e\\u0431\\u043b\\u0430\\u0441\\u0442\\u043d\\u044b\\u0445, \\u0432\\u0441\\u0435\\u0443\\u043a\\u0440\\u0430\\u0438\\u043d\\u0441\\u043a\\u0438\\u0445 \\u0438 \\u043c\\u0435\\u0436\\u0434\\u0443\\u043d\\u0430\\u0440\\u043e\\u0434\\u043d\\u044b\\u0445 \\u0432\\u044b\\u0441\\u0442\\u0430\\u0432\\u043a\\u0430\\u0445. \\u0412\\u044b\\u0441\\u0442\\u0430\\u0432\\u043b\\u044f\\u043b\\u0441\\u044f \\u0432 \\u0445\\u0443\\u0434\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0445 \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u044f\\u0445 \\u041a\\u0438\\u0435\\u0432\\u0430, \\u0430 \\u0442\\u0430\\u043a\\u0436\\u0435 \\u0427\\u0438\\u043a\\u0430\\u0433\\u043e \\u0438 \\u041c\\u0430\\u0439\\u0430\\u043c\\u0438 (\\u0421\\u0428\\u0410). \\u0421\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u0447\\u0430\\u043b \\u0441 \\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u043d\\u044b\\u043c \\u0447\\u0438\\u043a\\u0430\\u0433\\u0441\\u043a\\u0438\\u043c \\u0433\\u0430\\u043b\\u0435\\u0440\\u0438\\u0441\\u0442\\u043e\\u043c \\u0414\\u0436\\u043e\\u043d\\u043e\\u043c \\u041a\\u0430\\u0440\\u043b\\u0441\\u043e\\u043d\\u043e\\u043c. \\u0420\\u0430\\u0431\\u043e\\u0442\\u044b \\u043f\\u0440\\u043e\\u0434\\u0430\\u0432\\u0430\\u043b\\u0438\\u0441\\u044c \\u0432 \\u0447\\u0430\\u0441\\u0442\\u043d\\u043e\\u043c \\u043f\\u043e\\u0440\\u044f\\u0434\\u043a\\u0435, \\u0430 \\u0442\\u0430\\u043a\\u0436\\u0435 \\u043d\\u0430 \\u0432\\u044b\\u0441\\u0442\\u0430\\u0432\\u043a\\u0430\\u0445, \\u0432 \\u043c\\u0430\\u0433\\u0430\\u0437\\u0438\\u043d\\u0430\\u0445, \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u044f\\u0445 \\u0438 \\u043d\\u0430\\u0445\\u043e\\u0434\\u044f\\u0442\\u0441\\u044f \\u0432 \\u0447\\u0430\\u0441\\u0442\\u043d\\u044b\\u0445 \\u043a\\u043e\\u043b\\u043b\\u0435\\u043a\\u0446\\u0438\\u044f\\u0445 \\u0423\\u043a\\u0440\\u0430\\u0438\\u043d\\u044b, \\u0421\\u0428\\u0410, \\u0413\\u0435\\u0440\\u043c\\u0430\\u043d\\u0438\\u0438, \\u0418\\u0437\\u0440\\u0430\\u0438\\u043b\\u044f, \\u0410\\u0432\\u0441\\u0442\\u0440\\u0430\\u043b\\u0438\\u0438. \\u0425\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a \\u0436\\u0438\\u0432\\u0435\\u0442 \\u0438 \\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u0435\\u0442 \\u0432 \\u0427\\u0435\\u0440\\u043d\\u0438\\u0433\\u043e\\u0432\\u0435.\\\\r\\\\n\')\",\"time\":\"0.55\",\"slow\":false,\"file\":\"\\/Users\\/stepanorda\\/www\\/backend\\/app\\/Console\\/Commands\\/ConvertBio.php\",\"line\":37,\"hash\":\"ee9a3852bf99ec8959ed932b1cb3ac22\",\"hostname\":\"render.Home\"}','2023-04-19 17:04:48'),
