043a\\u043e\\u0439 \\u0433\\u0438\\u043c\\u043d\\u0430\\u0437\\u0438\\u0438 \\u0438\\u043c. \\u0413. \\u0421. \\u0420\\u0430\\u043a\\u043e\\u0432\\u0441\\u043a\\u043e\\u0433\\u043e (\\u043a\\u043e\\u0442\\u043e\\u0440\\u0443\\u044e \\u0441\\u0430\\u043c\\u0430 \\u0436\\u0435 \\u0437\\u0430\\u043a\\u043e\\u043d\\u0447\\u0438\\u043b\\u0430) \\u0442\\u0430\\u043a \\u0436\\u0435 \\u0432\\u0435\\u043b\\u0430 \\u043a\\u0440\\u0443\\u0436\\u043a\\u0438 \\u0432 \\u0420\\u0426\\u0414\\u042e\\u0422.\\\\r\\\\n\\u041d\\u043e\\u0432\\u044b\\u0439 \\u044d\\u0442\\u0430\\u043f \\u0432 \\u0436\\u0438\\u0437\\u043d\\u0438, \\u043d\\u0430\\u0441\\u0442\\u0443\\u043f\\u0430\\u0435\\u0442 \\u0432 2015 \\u0433\\u043e\\u0434\\u0443, \\u043a\\u043e\\u0433\\u0434\\u0430 \\u0431\\u0435\\u0441\\u0441\\u0430\\u0440\\u0430\\u0431\\u0441\\u043a\\u0430\\u044f \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u0446\\u0430 \\u043a\\u0430\\u0440\\u0434\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e \\u043c\\u0435\\u043d\\u044f\\u0435\\u0442 \\u0441\\u0432\\u043e\\u044e \\u0436\\u0438\\u0437\\u043d\\u044c \\u0438 \\u0440\\u0435\\u0448\\u0430\\u0435\\u0442\\u0441\\u044f \\u043d\\u0430 \\u043f\\u0435\\u0440\\u0435\\u0435\\u0437\\u0434 \\u0432 \\u0411\\u043e\\u043b\\u0433\\u0430\\u0440\\u0438\\u044e. \\u0422\\u0443\\u0442 \\u0410\\u043b\\u043b\\u0430 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e \\u0440\\u0430\\u0437\\u0432\\u0438\\u0432\\u0430\\u0435\\u0442 \\u0441\\u0432\\u043e\\u044e \\u0445\\u0443\\u0434\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u0443\\u044e \\u0434\\u0435\\u044f\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c, \\u043f\\u0438\\u0448\\u0435\\u0442 \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u044b, \\u0443\\u0447\\u0430\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442 \\u0432 \\u0432\\u044b\\u0441\\u0442\\u0430\\u0432\\u043a\\u0430\\u0445,\\u00a0\\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u0435\\u0442 \\u043d\\u0430\\u0434 \\u0434\\u0438\\u0437\\u