(4660,'98f85799-78d4-43c8-8202-8f59e9ba7678','98f8580a-ea0b-4ff9-8338-08dde9d4a394',NULL,1,'query','{\"connection\":\"mysql\",\"bindings\":[],\"sql\":\"insert into `user_bios` (`user_id`, `language`, `text`) values (57921, \'uk\', \'\\u0411\\u0406\\u041b\\u0418\\u0419 \\u0412\\u0406\\u041a\\u0422\\u041e\\u0420 \\u0414\\u041c\\u0418\\u0422\\u0420\\u041e\\u0412\\u0418\\u0427\\\\r\\\\n       \\u041d\\u0430\\u0440\\u043e\\u0434\\u0438\\u0432\\u0441\\u044f 21 \\u0431\\u0435\\u0440\\u0435\\u0437\\u043d\\u044f 1982 \\u0440.  \\u0443 \\u043c. \\u041a\\u043e\\u0441\\u0456\\u0432 \\u0406\\u0432\\u0430\\u043d\\u043e-\\u0424\\u0440\\u0430\\u043d\\u043a\\u0456\\u0432\\u0441\\u044c\\u043a\\u043e\\u0457 \\u043e\\u0431\\u043b. \\u0443 \\u0440\\u043e\\u0434\\u0438\\u043d\\u0456 \\u043c\\u0438\\u0442\\u0446\\u0456\\u0432.    \\u0421\\u0432\\u043e\\u0457\\u043c \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u044c\\u043a\\u0438\\u043c \\u043f\\u043e\\u043a\\u043b\\u0438\\u043a\\u0430\\u043d\\u043d\\u044f\\u043c \\u0437\\u0430\\u0432\\u0434\\u044f\\u0447\\u0443\\u044e \\u043c\\u0430\\u0442\\u0435\\u0440\\u0456, \\u043a\\u043e\\u0442\\u0440\\u0430 \\u043f\\u0440\\u0438\\u0432\\u0438\\u043b\\u0430 \\u043b\\u044e\\u0431\\u043e\\u0432 \\u0434\\u043e  \\u043f\\u0440\\u0435\\u043a\\u0440\\u0430\\u0441\\u043d\\u043e\\u0433\\u043e.\\\\r\\\\n\\\\r\\\\n         2003 \\u0440\\u043e\\u043a\\u0443 \\u0437\\u0430\\u043a\\u0456\\u043d\\u0447\\u0438\\u0432 \\u041a\\u043e\\u0441\\u0456\\u0432\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0434\\u0435\\u0440\\u0436\\u0430\\u0432\\u043d\\u0438\\u0439 \\u0456\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442 \\u043f\\u0440\\u0438\\u043a\\u043b\\u0430\\u0434\\u043d\\u043e\\u0433\\u043e \\u0442\\u0430 \\u0434\\u0435\\u043a\\u043e\\u0440\\u0430\\u0442\\u0438\\u0432\\u043d\\u043e\\u0433\\u043e \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432\\u0430 (\\u0432\\u0456\\u0434\\u0434\\u0456\\u043b \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0456\\u0445 \\u0432\\u0438\\u0440\\u043e\\u0431\\u0456\\u0432 \\u0437 \\u0434\\u0435\\u0440\\u0435\\u0432\\u0430, \\u041e\\u041a\\u0420 \\u00ab\\u0431\\u0430\\u043a\\u0430\\u043b\\u0430\\u0432\\u0440\\u00bb). \\u0412\\u0438\\u043a\\u043b\\u0430\\u0434\\u0430\\u0447\\u0456 \\u0456\\u0437 \\u0444\\u0430\\u0445\\u0443 - \\u042e\\u0441\\u0438\\u043f\\u0447\\u0443\\u043a \\u0420.\\u0411., \\u0411\\u0430\\u043b\\u0430\\u0433\\u0443\\u0440\\u0430\\u043a \\u0425.\\u0422., \\u0421\\u0442\\u0435\\u0444\\u0443\\u0440\\u0430\\u043a \\u0421.\\u0414.,  \\u0420\\u0430\\u0434\\u0438\\u0448 \\u041c.\\u0411.,  \\u041a\\u0440\\u0438\\u0446\\u043a\\u0430\\u043b\\u044e\\u043a \\u041e.\\u0406.   \\\\r\\\\n         2004-2005 \\u0440\\u0440. \\u2014 \\u043d\\u0430\\u0432\\u0447\\u0430\\u043d\\u043d\\u044f \\u0443 \\u041b\\u044c\\u0432\\u0456\\u0432\\u0441\\u044c\\u043a\\u0456\\u0439 \\u043d\\u0430\\u0446\\u0456\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0456\\u0439 \\u0430\\u043a\\u0430\\u0434\\u0435\\u043c\\u0456\\u0457 \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432 (\\u0444\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442 \\u00ab\\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0454 \\u0434\\u0435\\u0440\\u0435\\u0432\\u043e\\u00bb), \\u0434\\u0435 \\u043e\\u0442\\u0440\\u0438\\u043c\\u0430\\u0432 \\u043f\\u043e\\u0432\\u043d\\u0443 \\u0432\\u0438\\u0449\\u0443 \\u043e\\u0441\\u0432\\u0456\\u0442\\u0443 \\u0437\\u0430 \\u0441\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u044c\\u043d\\u0456\\u0441\\u0442\\u044e \\u201c\\u041e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0442\\u0432\\u043e\\u0440\\u0447\\u0435 \\u0442\\u0430 \\u0434\\u0435\\u043a\\u043e\\u0440\\u0430\\u0442\\u0438\\u0432\\u043d\\u043e-\\u043f\\u0440\\u0438\\u043a\\u043b\\u0430\\u0434\\u043d\\u0435 \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432\\u043e\\u201d \\u0439 \\u0437\\u0434\\u043e\\u0431\\u0443\\u0432 \\u043a\\u0432\\u0430\\u043b\\u0456\\u0444\\u0456\\u043a\\u0430\\u0446\\u0456\\u044e \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a\\u0430 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0456\\u0445 \\u0432\\u0438\\u0440\\u043e\\u0431\\u0456\\u0432 \\u0437 \\u0434\\u0435\\u0440\\u0435\\u0432\\u0430, \\u0434\\u043e\\u0441\\u043b\\u0456\\u0434\\u043d\\u0438\\u043a\\u0430, \\u0432\\u0438\\u043a\\u043b\\u0430\\u0434\\u0430\\u0447\\u0430. \\u0412\\u0438\\u043a\\u043b\\u0430\\u0434\\u0430\\u0447\\u0456 \\u0456\\u0437 \\u0444\\u0430\\u0445\\u0443 - \\u0421\\u043b\\u043e\\u0431\\u043e\\u0434\\u044f\\u043d \\u0410.\\u0419., \\u0413\\u0430\\u0440\\u0431\\u0443\\u0437 \\u0420.\\u0421, \\u0413\\u0440\\u0430\\u0431\\u0430\\u0440 \\u0414.\\u0406., \\u0421\\u0442\\u0435\\u0444\\\\\'\\u044e\\u043a \\u0406.\\u0412.  \\\\r\\\\n         2008 \\u0440\\u043e\\u043a\\u0443 \\u0437\\u0430\\u043a\\u0456\\u043d\\u0447\\u0438\\u0432 \\u0430\\u0441\\u043f\\u0456\\u0440\\u0430\\u043d\\u0442\\u0443\\u0440\\u0443 \\u041b\\u044c\\u0432\\u0456\\u0432\\u0441\\u044c\\u043a\\u043e\\u0457 \\u043d\\u0430\\u0446\\u0456\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0457 \\u0430\\u043a\\u0430\\u0434\\u0435\\u043c\\u0456\\u0457 \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432.\\\\r\\\\n         \\u0412\\u0456\\u0434 2009 \\u0440\\u043e\\u043a\\u0443 \\u043f\\u0440\\u0430\\u0446\\u044e\\u044e \\u0432\\u0438\\u043a\\u043b\\u0430\\u0434\\u0430\\u0447\\u0435\\u043c \\u0440\\u0438\\u0441\\u0443\\u043d\\u043a\\u0430 \\u0439 \\u0436\\u0438\\u0432\\u043e\\u043f\\u0438\\u0441\\u0443 \\u0432 \\u041a\\u0406\\u041f\\u0414\\u041c \\u041b\\u041d\\u0410\\u041c \\u043d\\u0430 \\u043a\\u0430\\u0444\\u0435\\u0434\\u0440\\u0456 \\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0442\\u0432\\u043e\\u0440\\u0447\\u043e\\u0433\\u043e \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432\\u0430 \\u0442\\u0430 \\u0430\\u043a\\u0430\\u0434\\u0435\\u043c\\u0456\\u0447\\u043d\\u0438\\u0445 \\u0434\\u0438\\u0441\\u0446\\u0438\\u043f\\u043b\\u0456\\u043d.      \\\\r\\\\n\\t\\\\r\\\\n2016 \\u0440\\u043e\\u043a\\u0443 \\u0437\\u0430\\u0445\\u0438\\u0441\\u0442\\u0438\\u0432 \\u0434\\u0438\\u0441\\u0435\\u0440\\u0442\\u0430\\u0446\\u0456\\u044e \\u0437\\u0430 \\u0441\\u043f\\u0435\\u0446\\u0456\\u0430\\u043b\\u044c\\u043d\\u0456\\u0441\\u0442\\u044e \\\\\\\"\\u0414\\u0435\\u043a\\u043e\\u0440\\u0430\\u0442\\u0438\\u0432\\u043d\\u0435 \\u0456 \\u043f\\u0440\\u0438\\u043a\\u043b\\u0430\\u0434\\u043d\\u0435 \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432\\u043e\\u201d \\u0442\\u0430 \\u0437\\u0434\\u043e\\u0431\\u0443\\u0432 \\u043d\\u0430\\u0443\\u043a\\u043e\\u0432\\u0438\\u0439 \\u0441\\u0442\\u0443\\u043f\\u0456\\u043d\\u044c \\u043a\\u0430\\u043d\\u0434\\u0438\\u0434\\u0430\\u0442\\u0430 \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432\\u043e\\u0437\\u043d\\u0430\\u0432\\u0441\\u0442\\u0432\\u0430.\\\\r\\\\n       \\u0422\\u0432\\u043e\\u0440\\u0447\\u0438\\u0439 \\u0448\\u043b\\u044f\\u0445 \\u0440\\u043e\\u0437\\u043f\\u043e\\u0447\\u0430\\u0432 \\u0456\\u0437 1999 \\u0440\\u043e\\u043a\\u0443.  \\u0423 \\u0440\\u043e\\u0431\\u043e\\u0442\\u0430\\u0445 \\u0437\\u0430\\u0441\\u0442\\u043e\\u0441\\u043e\\u0432\\u0443\\u044e \\u0440\\u043e\\u0437\\u043c\\u0430\\u0457\\u0442\\u0442\\u044f \\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0442\\u0432\\u043e\\u0440\\u0447\\u0438\\u0445 \\u0441\\u044e\\u0436\\u0435\\u0442\\u0456\\u0432 \\u0442\\u0430 \\u0442\\u0435\\u043c: \\u043f\\u043e\\u0440\\u0442\\u0440\\u0435\\u0442\\u0438, \\u043d\\u0430\\u0442\\u044e\\u0440\\u043c\\u043e\\u0440\\u0442\\u0438, \\u043f\\u0435\\u0439\\u0437\\u0430\\u0436\\u0456, \\u0444\\u0456\\u0433\\u0443\\u0440\\u0430\\u0442\\u0438\\u0432\\u043d\\u0456 \\u043a\\u043e\\u043c\\u043f\\u043e\\u0437\\u0438\\u0446\\u0456\\u0457.\\\\r\\\\n       \\u0415\\u043a\\u0441\\u043f\\u043e\\u043d\\u0443\\u0432\\u0430\\u0432  \\u0441\\u0432\\u043e\\u0457 \\u0440\\u043e\\u0431\\u043e\\u0442\\u0438 \\u043d\\u0430 \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0438\\u0445 \\u0432\\u0438\\u0441\\u0442\\u0430\\u0432\\u043a\\u0430\\u0445: \\u0443 \\u043c\\u0443\\u0437\\u0435\\u0457 \\u041c. \\u0411\\u0456\\u043b\\u0430\\u0441\\u0430 (\\u0422\\u0440\\u0443\\u0441\\u043a\\u0430\\u0432\\u0435\\u0446\\u044c), \\u043c\\u0443\\u0437\\u0435\\u0457 \\u0456\\u0441\\u0442\\u043e\\u0440\\u0456\\u0457 \\u0422\\u0440\\u0443\\u0441\\u043a\\u0430\\u0432\\u0446\\u044f, \\u0432\\u0438\\u0441\\u0442\\u0430\\u0432\\u043a\\u043e\\u0432\\u0456\\u0439 \\u0437\\u0430\\u043b\\u0456 \\u041a\\u043e\\u0441\\u0456\\u0432\\u0441\\u044c\\u043a\\u043e\\u0457 \\u0440\\u0435\\u0433\\u0456\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0457 \\u043e\\u0440\\u0433\\u0430\\u043d\\u0456\\u0437\\u0430\\u0446\\u0456\\u0457 \\u041d\\u0430\\u0446\\u0456\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0457 \\u0441\\u043f\\u0456\\u043b\\u043a\\u0438 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a\\u0456\\u0432 \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0438, \\u041a\\u043e\\u0441\\u0456\\u0432\\u0441\\u044c\\u043a\\u043e\\u043c\\u0443 \\u0456\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442\\u0456 \\u043f\\u0440\\u0438\\u043a\\u043b\\u0430\\u0434\\u043d\\u043e\\u0433\\u043e \\u0442\\u0430 \\u0434\\u0435\\u043a\\u043e\\u0440\\u0430\\u0442\\u0438\\u0432\\u043d\\u043e\\u0433\\u043e \\u043c\\u0438\\u0441\\u0442\\u0435\\u0446\\u0442\\u0432\\u0430, \\u0440\\u0430\\u0439\\u043e\\u043d\\u043d\\u0456\\u0439 \\u0431\\u0456\\u0431\\u043b\\u0456\\u043e\\u0442\\u0435\\u0446\\u0456 \\u043c. \\u0413\\u043e\\u0440\\u043e\\u0434\\u0435\\u043d\\u043a\\u0438, \\u0431\\u0443\\u0434\\u0438\\u043d\\u043a\\u0443 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0443\\u0440\\u0438 \\u0441. \\u0427\\u0435\\u0440\\u043d\\u044f\\u0442\\u0438\\u043d, \\u0430 \\u0442\\u0430\\u043a\\u043e\\u0436 \\u0443\\u0447\\u0430\\u0441\\u043d\\u0438\\u043a \\u043e\\u0431\\u043b\\u0430\\u0441\\u043d\\u0438\\u0445 (\\u0406\\u0432\\u0430\\u043d\\u043e-\\u0424\\u0440\\u0430\\u043d\\u043a\\u0456\\u0432\\u0441\\u044c\\u043a) \\u0442\\u0430 \\u0432\\u0441\\u0435\\u0443\\u043a\\u0440\\u0430\\u0457\\u043d\\u0441\\u044c\\u043a\\u0438\\u0445 (\\u041a\\u0438\\u0457\\u0432, \\u0425\\u0430\\u0440\\u043a\\u0456\\u0432, \\u041b\\u044c\\u0432\\u0456\\u0432) \\u0432\\u0438\\u0441\\u0442\\u0430\\u0432\\u043e\\u043a.\\\\r\\\\n      \\u0411\\u0440\\u0430\\u0432 \\u0443\\u0447\\u0430\\u0441\\u0442\\u044c \\u0443 \\u0440\\u043e\\u0437\\u043f\\u0438\\u0441\\u0456 \\u0442\\u0430\\u043a\\u0438\\u0445 \\u0445\\u0440\\u0430\\u043c\\u0456\\u0432: \\u0423\\u0441\\u043f\\u0456\\u043d\\u043d\\u044f \\u041f\\u0440\\u0435\\u0441\\u0432\\u044f\\u0442\\u043e\\u0457 \\u0411\\u043e\\u0433\\u043e\\u0440\\u043e\\u0434\\u0438\\u0446\\u0456 (\\u0406\\u0432\\u0430\\u043d\\u043e-\\u0424\\u0440\\u0430\\u043d\\u043a\\u0456\\u0432\\u0441\\u044c\\u043a\\u0430 \\u043e\\u0431\\u043b., \\u0413\\u043e\\u0440\\u043e\\u0434\\u0435\\u043d\\u043a\\u0456\\u0432\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0440-\\u043d., \\u0441.\\u0427\\u0435\\u0440\\u043d\\u044f\\u0442\\u0438\\u043d), (\\u0406\\u0432\\u0430\\u043d\\u043e-\\u0424\\u0440\\u0430\\u043d\\u043a\\u0456\\u0432\\u0441\\u044c\\u043a\\u0430 \\u043e\\u0431\\u043b., \\u0413\\u043e\\u0440\\u043e\\u0434\\u0435\\u043d\\u043a\\u0456\\u0432\\u0441\\u044c\\u043a\\u0438\\u0439 \\u0440-\\u043d., \\u0441.\\u0420\\u0435\\u043f\\u0443\\u0436\\u0438\\u043d\\u0446\\u0456), \\u0421\\u0432. \\u041c\\u0438\\u043a\\u043e\\u043b\\u0430\\u044f (\\u041e\\u0434\\u0435\\u0441\\u044c\\u043a\\u0430 \\u043e\\u0431\\u043b., \\u043c. \\u041a\\u0456\\u043b\\u0456\\u044f). \\\\r\\\\n     \\u0414\\u043e\\u0441\\u043b\\u0456\\u0434\\u0436\\u0443\\u044e \\u0442\\u0432\\u043e\\u0440\\u0447\\u0456\\u0441\\u0442\\u044c \\u0441\\u0443\\u0447\\u0430\\u0441\\u043d\\u0438\\u0445 \\u043c\\u0438\\u0442\\u0446\\u0456\\u0432 \\u041a\\u043e\\u0441\\u0456\\u0432\\u0449\\u0438\\u043d\\u0438 \\u0432 \\u0433\\u0430\\u043b\\u0443\\u0437\\u0456 \\u0434\\u0435\\u043a\\u043e\\u0440\\u0430\\u0442\\u0438\\u0432\\u043d\\u043e-\\u043f\\u0440\\u0438\\u043a\\u043b\\u0430\\u0434\\u043d\\u04