r\\\\n\\u041e\\u0441\\u043d\\u043e\\u0432\\u043d\\u0430 \\u0442\\u0435\\u043c\\u0430 \\u0442\\u0432\\u043e\\u0440\\u0447\\u043e\\u0441\\u0442\\u0456, \\u044f\\u043a\\u0443 \\u043c\\u0438\\u0442\\u0435\\u0446\\u044c \\u0440\\u043e\\u0437\\u0432\\\\\'\\u044f\\u0437\\u0443\\u0432\\u0430\\u0432 \\u0432 \\u0435\\u043a\\u0441\\u043f\\u0440\\u0435\\u0441\\u0438\\u0432\\u043d\\u043e\\u043c\\u0443, \\u0430 \\u0442\\u043e \\u0439 \\u0434\\u0440\\u0430\\u043c\\u0430\\u0442\\u0438\\u0447\\u043d\\u043e\\u043c\\u0443 \\u043a\\u043b\\u044e\\u0447\\u0456, \\u2014 \\u0434\\u043e\\u043b\\u044f \\u0443\\u043a\\u0440\\u0430\\u0457\\u043d\\u0441\\u044c\\u043a\\u043e\\u0457 \\u0436\\u0456\\u043d\\u043a\\u0438-\\u0441\\u0435\\u043b\\u044f\\u043d\\u043a\\u0438 \\u043d\\u0430 \\u0442\\u043b\\u0456 \\u0456\\u0441\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u0438\\u0445 \\u043f\\u043e\\u0442\\u0440\\u044f\\u0441\\u0456\\u043d\\u044c \\u043f\\u043e\\u0432\\u043e\\u0454\\u043d\\u043d\\u043e\\u0433\\u043e \\u0447\\u0430\\u0441\\u0443. \\u0419\\u043e\\u0433\\u043e \\u043e\\u0431\\u0440\\u0430\\u0437\\u0430\\u043c \\u043f\\u0440\\u0438\\u0442\\u0430\\u043c\\u0430\\u043d\\u043d\\u0456 \\u0435\\u043f\\u0456\\u0447\\u043d\\u0456\\u0441\\u0442\\u044c \\u0456 \\u0441\\u0438\\u043c\\u0432\\u043e\\u043b\\u0456\\u0437\\u043c. \\u0417\\u0430 \\u0441\\u0435\\u0440\\u0456\\u044e \\u0436\\u0438\\u0432\\u043e\\u043f\\u0438\\u0441\\u043d\\u0438\\u0445 \\u0440\\u043e\\u0431\\u0456\\u0442 \\u00ab\\u0416\\u0456\\u043d\\u043e\\u0447\\u0430 \\u0434\\u043e\\u043b\\u044f\\u00bb \\u043e\\u0442\\u0440\\u0438\\u043c\\u0430\\u0432 \\u0434\\u0438\\u043f\\u043b\\u043e\\u043c 1-\\u0433\\u043e \\u0441\\u0442\\u0443\\u043f\\u0435\\u043d\\u044e \\u041c\\u0456\\u043d-\\u0432\\u0430 \\u043a\\u0443\\u043b\\u044c\\u0442\\u0443\\u0440\\u0438 \\u0456 \\u043c\\u0438\\u0441\\u0442-\\u0432 (2000). \\u041f\\u0440\\u0430\\u0446\\u044e\\u0432\\u0430\\u0432 \\u0442\\u0430\\u043a\\u043e\\u0436 \\u0443 \\u0436\\u0430\\u043d\\u0440\\u0430\\u044