041f\\u0423 \\u0438\\u043c. \\u0428\\u043e\\u043b\\u043e\\u0445\\u043e\\u0432\\u0430.\\\\r\\\\n\\\\r\\\\n\\u0412\\u044b\\u0441\\u0442\\u0430\\u0432\\u043b\\u044f\\u043b\\u0430 \\u0441\\u0432\\u043e\\u0438 \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u044b \\u0432 \\u0426\\u0414\\u0425 \\u0432 \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u0435 \\u201c\\u0420\\u043e\\u0434\\u0438\\u043d\\u0430\\u201d, \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u0435 \\u201cSummertime\\u201d, \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u0435 \\u201c\\u0410\\u0440\\u0442-\\u0433\\u043e\\u0441\\u0442\\u0438\\u043d\\u0430\\u044f\\u201d, \\u0432 \\u043c\\u0443\\u0437\\u0435\\u0435 \\u041c\\u043e\\u0434\\u044b \\u0432 \\u041c\\u0430\\u043d\\u0435\\u0436\\u0435, \\u043c\\u0443\\u0437\\u0435\\u0435 \\u0410\\u0440\\u0442-\\u0414\\u0435\\u043a\\u043e, \\u0426\\u0414\\u0425, \\u043c\\u0443\\u0437\\u0435\\u0435 \\u041e\\u0441\\u0442\\u0440\\u043e\\u0432\\u0441\\u043a\\u043e\\u0433\\u043e, \\u0432 \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u0435 \\u201c\\u0417\\u043e\\u043b\\u043e\\u0442\\u0430\\u044f \\u043a\\u0430\\u043b\\u0438\\u043f\\u0441\\u043e\\u201d \\u0432 \\u041b\\u0443\\u0432\\u0440\\u0435, \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u0435 \\u201c\\u041d\\u0430 \\u041a\\u0430\\u0448\\u0438\\u0440\\u043a\\u0435\\u201d. \\u0410 \\u0442\\u0430\\u043a\\u0436\\u0435: \\u0443\\u0447\\u0430\\u0441\\u0442\\u0432\\u043e\\u0432\\u0430\\u043b\\u0430 \\u0432 \\u0432\\u044b\\u0441\\u0442\\u0430\\u0432\\u043a\\u0435 \\u201c\\u0420\\u0435\\u0432\\u043e\\u043b\\u044e\\u0446\\u0438\\u044f\\u201d \\u041a\\u0443\\u0431\\u0430, \\u0432 \\u0432\\u044b\\u0441\\u0442\\u0430\\u0432\\u043a\\u0435 \\u201c\\u0417\\u0434\\u043e\\u0440\\u043e\\u0432\\u044b\\u0439 \\u043e\\u0431\\u0440\\u0430\\u0437\\u201d \\u0410\\u0440\\u0442\\u043f\\u043b\\u0435\\u0439, \\u0431\\u044b\\u043b\\u0430 \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u0432\\u044b\\u0441\\u0442\\u0430\\u0432\\u043a\\u0430 \\u0432 \\u201cGoldenHole\\u201d \\u0438 \\u0434\\u0440\\u0443\\u0433\\u0438\\u0435 \\u043c\\u043d\\u043e\\u0433\\u043e\\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0432\\u044b\\u0441\\u0442\\u0430\\u0432\\u043a\\u0438 \\u043f\\u043e \\u0420\\u043e\\u0441\\u0441\\u0438\\u0438 \\u0438 \\u043c\\u0438\\u0440\\u0443!\\\\r\\\\n\\\\r\\\\n\\u0412 2006 \\u0433. \\u0432\\u043e\\u0448\\u043b\\u0430 \\u0432 \\u0421\\u043e\\u044e\\u0437 \\u0433\\u0440\\u0430\\u0444\\u0438\\u043a\\u043e\\u0432 \\u0420\\u043e\\u0441\\u0441\\u0438\\u0438.\\\\r\\\\n\\\\r\\\\n2014 \\u0433. \\u2013 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a \\u043f\\u043e \\u043e\\u0444\\u043e\\u0440\\u043c\\u043b\\u0435\\u043d\\u0438\\u044e \\u0436\\u0443\\u0440\\u043d\\u0430\\u043b\\u0430 \\u00ab\\u041b\\u0438\\u0442\\u0435\\u0440\\u0430\\u0442\\u0443\\u0440\\u043d\\u0430\\u044f \\u0433\\u043e\\u0441\\u0442\\u0438\\u043d\\u0430\\u044f\\u00bb.\\\\r\\\\n2015 \\u0433. \\u2013 \\u0432\\u044b\\u0441\\u0442\\u0430\\u0432\\u043a\\u0430 \\u0432 \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u0435 \\u00abSummertime\\u00bb.\\\\r\\\\n2014 \\u2013 2015 \\u0433. \\u0441\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u0447\\u0430\\u043b\\u0430 \\u0441 Dubo, Rama (\\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u044f \\u043f\\u043e\\u0441\\u0442\\u0435\\u0440\\u043e\\u0432).\\\\r\\\\n\\u0441 2015 \\u0433. \\u2013 \\u0441\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u0447\\u0430\\u0435\\u0442 \\u0441 \\u0444\\u0438\\u0440\\u043c\\u043e\\u0439 \\u043f\\u043e \\u0438\\u0437\\u0433\\u043e\\u0442\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u044e \\u043c\\u043e\\u0437\\u0430\\u0438\\u043a\\u0438.\\\\r\\\\n\\u0441 2015 \\u0433. \\u2013 \\u0441\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u0447\\u0430\\u0435\\u0442 \\u0441 \\u0433\\u0430\\u043b\\u0435\\u0440\\u0435\\u0435\\u0439 \\u00ab\\u0410\\u0440\\u0442-\\u0433\\u043e\\u0441\\u0442\\u0438\\u043d\\u0430\\u044f\\u00bb.\\\\r\\\\n2017 \\u0