(4764,'98f8579a-583c-4560-972c-97b6eb5cae18','98f8580a-ea0b-4ff9-8338-08dde9d4a394',NULL,1,'query','{\"connection\":\"mysql\",\"bindings\":[],\"sql\":\"insert into `user_bios` (`user_id`, `language`, `text`) values (57307, \'uk\', \'\\u041d\\u0430\\u0442\\u044e\\u0440\\u043c\\u043e\\u0440\\u0442\\u044b, \\u0438\\u043c\\u043f\\u0440\\u0435\\u0441\\u0441\\u0438\\u043e\\u043d\\u0438\\u0441\\u0442\\u0441\\u043a\\u0438\\u0435, \\u0430 \\u0442\\u0430\\u043a\\u0436\\u0435 \\u0441\\u044e\\u0440\\u0440\\u0435\\u0430\\u043b\\u0438\\u0441\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u044b, \\u0441\\u043e\\u0437\\u0434\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0442\\u0430\\u043b\\u0430\\u043d\\u0442\\u043b\\u0438\\u0432\\u044b\\u043c \\u0438 \\u043e\\u043f\\u044b\\u0442\\u043d\\u044b\\u043c \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a\\u043e\\u043c \\u0418\\u0440\\u0438\\u043d\\u043e\\u0439 \\u041c\\u0443\\u0441\\u0438\\u0435\\u043d\\u043a\\u043e.\\\\r\\\\n\\u0417\\u0434\\u0440\\u0430\\u0432\\u0441\\u0442\\u0432\\u0443\\u0439\\u0442\\u0435! \\u041c\\u0435\\u043d\\u044f \\u0437\\u043e\\u0432\\u0443\\u0442 \\u0418\\u0440\\u0438\\u043d\\u0430.\\\\r\\\\n\\\\r\\\\n\\u0412 \\u0434\\u0435\\u0442\\u0441\\u0442\\u0432\\u0435 \\u044f \\u0440\\u0438\\u0441\\u043e\\u0432\\u0430\\u043b\\u0430, \\u0438 \\u044d\\u0442\\u0430 \\u0441\\u0442\\u0440\\u0430\\u0441\\u0442\\u044c \\u0440\\u043e\\u0441\\u043b\\u0430 \\u0432\\u043e \\u043c\\u043d\\u0435 \\u0433\\u043e\\u0434\\u0430\\u043c\\u0438. \\u041c\\u043e\\u0438 \\u043d\\u0430\\u0432\\u044b\\u043a\\u0438 \\u0431\\u044b\\u043b\\u0438 \\u0443\\u0441\\u043e\\u0432\\u0435\\u0440\\u0448\\u0435\\u043d\\u0441\\u0442\\u0432\\u043e\\u0432\\u0430\\u043d\\u044b \\u0431\\u043b\\u0430\\u0433\\u043e\\u0434\\u0430\\u0440\\u044f \\u043a\\u0440\\u043e\\u043f\\u043e\\u0442\\u043b\\u0438\\u0432\\u043e\\u043c\\u0443 \\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u044e \\u0438 \\u043f\\u043e\\u0441\\u0442\\u043e\\u044f\\u043d\\u043d\\u044b\\u043c \\u0442\\u0440\\u0435\\u043d\\u0438\\u0440\\u043e\\u0432\\u043a\\u0430\\u043c. \\u041a\\u0430\\u0436\\u0434\\u0430\\u044f \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u0430 - \\u044d\\u0442\\u043e \\u043d\\u0430\\u0441\\u0442\\u043e\\u044f\\u0449\\u0435\\u0435 \\u0438\\u0441\\u043a\\u0443\\u0441\\u0441\\u0442\\u0432\\u043e \\u0441\\u043e\\u0447\\u0435\\u0442\\u0430\\u043d\\u0438\\u044f \\u0446\\u0432\\u0435\\u0442\\u043e\\u0432 \\u0438 \\u0442\\u0435\\u043d\\u0435\\u0439, \\u0441\\u043e\\u0437\\u0434\\u0430\\u043d\\u043d\\u043e\\u0435 \\u0441 \\u043e\\u0441\\u043e\\u0431\\u044b\\u043c\\u0438 \\u0447\\u0443\\u0432\\u0441\\u0442\\u0432\\u0430\\u043c\\u0438. \\u042d\\u0442\\u043e \\u043c\\u043e\\u0436\\u0435\\u0442 \\u0431\\u044b\\u0442\\u044c \\u043d\\u0435\\u0436\\u043d\\u043e\\u0441\\u0442\\u044c, \\u0441\\u0442\\u0440\\u0430\\u0441\\u0442\\u044c, \\u0433\\u0440\\u0443\\u0441\\u0442\\u044c, \\u0440\\u0430\\u0434\\u043e\\u0441\\u0442\\u044c \\u0438 \\u043a\\u043e\\u043d\\u0435\\u0447\\u043d\\u043e \\u0436\\u0435 \\u043b\\u044e\\u0431\\u043e\\u0432\\u044c. \\u041c\\u043e\\u044f \\u0446\\u0435\\u043b\\u044c - \\u0441\\u043e\\u0437\\u0434\\u0430\\u0442\\u044c \\u0445\\u043e\\u0440\\u043e\\u0448\\u0435\\u0435 \\u043d\\u0430\\u0441\\u0442\\u0440\\u043e\\u0435\\u043d\\u0438\\u0435, \\u043f\\u043e\\u0432\\u044b\\u0441\\u0438\\u0442\\u044c \\u043a\\u043e\\u043c\\u0444\\u043e\\u0440\\u0442 \\u0432 \\u0432\\u0430\\u0448\\u0435\\u043c \\u0434\\u043e\\u043c\\u0435 (\\u0441 \\u043f\\u043e\\u043c\\u043e\\u0449\\u044c\\u044e \\u0432\\u0435\\u043b\\u0438\\u043a\\u043e\\u043b\\u0435\\u043f\\u043d\\u043e\\u0433\\u043e \\u043d\\u0430\\u0442\\u044e\\u0440\\u043c\\u043e\\u0440\\u0442\\u0430), \\u043f\\u043e\\u0434\\u0430\\u0440\\u0438\\u0442\\u044c \\u043f\\u043e\\u0437\\u0438\\u0442\\u0438\\u0432\\u043d\\u0443\\u044e \\u044d\\u043d\\u0435\\u0440\\u0433\\u0438\\u044e, \\u0443\\u043a\\u0440\\u0435\\u043f\\u0438\\u0442\\u044c \\u0436\\u0438\\u0437\\u043d\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0434\\u0443\\u0445 (\\u0441 \\u043f\\u043e\\u043c\\u043e\\u0449\\u044c\\u044e \\u0441\\u044e\\u0440\\u0440\\u0435\\u0430\\u043b\\u0438\\u0441\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0445 \\u0438 \\u0430\\u0431\\u0441\\u0442\\u0440\\u0430\\u043a\\u0442\\u043d\\u044b\\u0445 \\u0440\\u0430\\u0431\\u043e\\u0442). \\u042f \\u0432\\u043a\\u043b\\u0430\\u0434\\u044b\\u0432\\u0430\\u044e \\u043f\\u043e\\u0437\\u0438\\u0442\\u0438\\u0432\\u043d\\u0443\\u044e \\u044d\\u043d\\u0435\\u0440\\u0433\\u0438\\u044e \\u0438 \\u043d\\u0430\\u0441\\u0442\\u043e\\u044f\\u0449\\u0443\\u044e \\u043b\\u044e\\u0431\\u043e\\u0432\\u044c \\u0432 \\u043a\\u0430\\u0436\\u0434\\u0443\\u044e \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u0443 \\u0438 \\u0445\\u043e\\u0447\\u0443 \\u043f\\u043e\\u0434\\u0435\\u043b\\u0438\\u0442\\u044c\\u0441\\u044f \\u044d\\u0442\\u0438\\u043c\\u0438 \\u0447\\u0443\\u0432\\u0441\\u0442\\u0432\\u0430\\u043c\\u0438 \\u0441 \\u0434\\u0440\\u0443\\u0433\\u0438\\u043c\\u0438 \\u043b\\u044e\\u0434\\u044c\\u043c\\u0438.\\\\r\\\\n\\\\r\\\\n\\u041e\\u0442\\u043a\\u0440\\u044b\\u0442\\u0438\\u0435 \\u00abArts.In.UA\\u00bb - \\u0432\\u0430\\u0436\\u043d\\u044b\\u0439 \\u0448\\u0430\\u0433 \\u0434\\u043b\\u044f \\u043c\\u0435\\u043d\\u044f. \\u042f \\u0441\\u0447\\u0430\\u0441\\u0442\\u043b\\u0438\\u0432\\u0430 \\u0432\\u0441\\u0442\\u0440\\u0435\\u0442\\u0438\\u0442\\u044c \\u043b\\u044e\\u0434\\u0435\\u0439 \\u0438\\u0437 \\u0440\\u0430\\u0437\\u043d\\u044b\\u0445 \\u0441\\u0442\\u0440\\u0430\\u043d \\u0438 \\u043d\\u043e\\u0432\\u044b\\u0445 \\u0445\\u0443\\u0434\\u043e\\u0436\\u043d\\u0438\\u043a\\u043e\\u0432. \\u041c\\u043e\\u0438\\u043c\\u0438 \\u0432\\u0434\\u043e\\u0445\\u043d\\u043e\\u0432\\u0438\\u0442\\u0435\\u043b\\u044f\\u043c\\u0438 \\u0431\\u044b\\u043b\\u0438 \\u0421\\u0430\\u043b\\u044c\\u0432\\u0430\\u0434\\u043e\\u0440 \\u0414\\u0430\\u043b\\u0438, \\u041f\\u0430\\u0431\\u043