41\\u0435 \\u043a\\u0430\\u043a \\u043d\\u0430 \\u0444\\u043e\\u0442\\u043e-\\u044f \\u0440\\u0435\\u0448\\u0438\\u043b\\u0430, \\u0447\\u0442\\u043e \\u043a\\u0443\\u043f\\u043b\\u044e \\u0431\\u043e\\u043b\\u044c\\u0448\\u043e\\u0439 \\u0445\\u043e\\u043b\\u0441\\u0442 \\u0438 \\u043d\\u0430\\u0440\\u0438\\u0441\\u0443\\u044e \\u0441\\u0432\\u043e\\u044e \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u0443. \\u042d\\u0442\\u043e \\u0431\\u044b\\u043b\\u0430 \\u041f\\u043e\\u0440\\u0442\\u0443\\u0433\\u0430\\u043b\\u0438\\u044f, \\u0431\\u0435\\u0440\\u0435\\u0433 \\u043d\\u0430 \\u043a\\u0440\\u0430\\u044e \\u0437\\u0435\\u043c\\u043b\\u0438, \\u0433\\u0434\\u0435 \\u043c\\u044b \\u0441 \\u043c\\u0443\\u0436\\u0435\\u043c \\u043f\\u043e\\u0436\\u0435\\u043d\\u0438\\u043b\\u0438\\u0441\\u044c, \\u044f \\u043f\\u0440\\u0435\\u0437\\u0435\\u043d\\u0442\\u043e\\u0432\\u0430\\u043b\\u0430 \\u0435\\u043c\\u0443 \\u044d\\u0442\\u0443 \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u0443. \\u0410 \\u0434\\u0430\\u043b\\u044c\\u0448\\u0435 \\u043d\\u0430\\u0447\\u0430\\u043b\\u0430 \\u0438\\u0441\\u043a\\u0430\\u0442\\u044c \\u0447\\u0442\\u043e \\u0436\\u0435 \\u044f \\u0445\\u043e\\u0442\\u0435\\u043b\\u0430 \\u0431\\u044b \\u0440\\u0438\\u0441\\u043e\\u0432\\u0430\\u0442\\u044c \\u0438 \\u043a\\u0430\\u043a \\u0440\\u0438\\u0441\\u043e\\u0432\\u0430\\u0442\\u044c \\u0438 \\u0447\\u0435\\u043c, \\u0432 \\u043a\\u0430\\u043a\\u043e\\u0439 \\u0442\\u0435\\u0445\\u043d\\u0438\\u043a\\u0435. \\u041d\\u0430\\u0447\\u0430\\u043b\\u0438\\u0441\\u044c \\u043f\\u043e\\u043f\\u044b\\u0442\\u043a\\u0438, \\u043f\\u043e\\u0438\\u0441\\u043a\\u0438 \\u0441\\u0432\\u043e\\u0435\\u0433\\u043e \\u0441\\u0442\\u0438\\u043b\\u044f. \\u0411\\u044b\\u043b\\u0438 \\u043d\\u0435\\u0443\\u0434\\u0430\\u0447\\u043d\\u044b\\u0435 \\u043a\\u0430\\u0440\\u0442\\u0438\\u043d\\u044b, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0435 \\u044f \\u0437\\u0430\\u0440\\u0438\\u0441\\u043e\\u0432\\u044b\\u0432\\u